using namespace std;

using ull = unsigned long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ull x, y;
    cin >> x >> y;

    if (std::gcd(x, y) != 1) {
        cout << "Impossible";
        return 0;
    }

    while (x != y) {
        if (x > y) {
            ull count = (x - 1) / y;
            cout << count << 'A';
            x -= count * y;
        } else {
            ull count = (y - 1) / x;
            cout << count << 'B';
            y -= count * x;
        }
    }

    return 0;
}

