#include <bits/stdc++.h>
using namespace std;

using ull = unsigned long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ull x, y;
    cin >> x >> y;

    if (x == 0 || y == 0 || std::gcd(x, y) != 1) {
        cout << "Impossible";
        return 0;
    }

    vector<pair<ull, char>> ans;

    while (x != y) {
        if (x > y) {
            ull count = (x - 1) / y;
            ans.emplace_back(count, 'A');
            x -= count * y;
        } else {
            ull count = (y - 1) / x;
            ans.emplace_back(count, 'B');
            y -= count * x;
        }
    }

    for (const auto &[count, operation] : ans)
        cout << count << operation;

    return 0;
}

